const body = $json.body || {};
const positions = Array.isArray(body.positions) ? body.positions : [];

const parseAmt = (a) => { const n = parseFloat(String(a == null ? '' : a).replace(/\s/g, '').replace(',', '.')); return isNaN(n) ? 0 : n; };
const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const getPriznak = (p) => (p.classification && p.classification.признак) || p.признак || 'спорно';
const getStatya = (p) => (p.classification && p.classification.статья) || p.статья || 'Прочее';
const getName = (p) => p.name || getStatya(p);
const getObosn = (p) => (p.classification && p.classification.обоснование) || p.обоснование || null;
const getSsylka = (p) => (p.classification && p.classification.ссылка) || p.ссылка || null;

const seen = {};
const dupes = [];
const unique = [];
for (const p of positions) {
  const docNum = p.doc_number ? String(p.doc_number).trim() : '';
  const name = (p.name || (p.classification && p.classification.статья) || '').trim().toLowerCase();
  const amt = parseAmt(p.amount);
  const k = docNum ? `${docNum}::${name}::${amt}` : null;
  if (k && seen[k]) { dupes.push(p); continue; }
  if (k) seen[k] = true;
  unique.push(p);
}

const byStatya = {};
let itogo = 0;
let uchteno = 0;
const excluded = [];
const disputed = [];
const detail = [];
for (const p of unique) {
  const amt = parseAmt(p.amount);
  const priznak = getPriznak(p);
  const statya = getStatya(p);
  const name = getName(p);
  const obosn = getObosn(p);
  const ssylka = getSsylka(p);

  detail.push({ id: p.id || null, наименование: name, статья: statya, признак: priznak, сумма: amt, doc_number: p.doc_number || null, обоснование: obosn, ссылка: ssylka });

  if (priznak === 'учитывается') {
    byStatya[statya] = round2((byStatya[statya] || 0) + amt);
    itogo = round2(itogo + amt);
    uchteno += 1;
  } else if (priznak === 'не_учитывается') {
    excluded.push({ статья: statya, наименование: name, сумма: amt, id: p.id, doc_number: p.doc_number || null, обоснование: obosn, ссылка: ssylka });
  } else {
    disputed.push({ статья: statya, наименование: name, сумма: amt, id: p.id, doc_number: p.doc_number || null, обоснование: obosn, ссылка: ssylka });
  }
}

return { json: {
  job_id: body.job_id || null,
  смета: { по_статьям: byStatya, итого: itogo },
  исключено: excluded,
  спорные_на_проверку: disputed,
  дубликаты: dupes,
  все_позиции: detail,
  всего_позиций: positions.length,
  учтено_позиций: uchteno
} };
